  let liveSyncDebounceTimer = null;
  function debouncedSyncLiveState(delay = 120) {
    if (state.obsMode !== false) {
      if (liveSyncDebounceTimer) clearTimeout(liveSyncDebounceTimer);
      liveSyncDebounceTimer = setTimeout(() => {
        saveUserSettings();
        syncLiveState();
      }, delay);
    } else {
      saveUserSettings();
      syncLiveState();
    }
  }

  function generateShareableStyleUrl() {
    const url = new URL(window.location.href.split('?')[0].split('#')[0]);
    if (state.selectedFont) url.searchParams.set('font', state.selectedFont);
    if (state.fontSize) url.searchParams.set('size', state.fontSize);
    if (state.styleOptions?.textColor) url.searchParams.set('color', state.styleOptions.textColor);
    if (state.styleOptions?.strokeWidth) url.searchParams.set('sw', state.styleOptions.strokeWidth);
    if (state.styleOptions?.strokeColor) url.searchParams.set('sc', state.styleOptions.strokeColor);
    if (state.styleOptions?.shadowDistance) url.searchParams.set('sd', state.styleOptions.shadowDistance);
    if (state.styleOptions?.shadowBlur) url.searchParams.set('sb', state.styleOptions.shadowBlur);
    if (state.styleOptions?.shadowColor) url.searchParams.set('sh', state.styleOptions.shadowColor);
    if (state.chromaKey) url.searchParams.set('chroma', state.chromaKey);
    if (state.presentationMode) url.searchParams.set('mode', state.presentationMode);
    if (state.styleOptions?.boxBgColor) url.searchParams.set('boxBg', state.styleOptions.boxBgColor);
    if (state.styleOptions?.boxOpacity !== undefined) url.searchParams.set('boxOp', state.styleOptions.boxOpacity);
    if (state.styleOptions?.boxRadius !== undefined) url.searchParams.set('boxRad', state.styleOptions.boxRadius);
    if (state.styleOptions?.boxPadding !== undefined) url.searchParams.set('boxPad', state.styleOptions.boxPadding);
    if (state.textAnimation) url.searchParams.set('anim', state.textAnimation);

    return url.toString();
  }

  function applyUrlStyleSettings() {
    const params = new URLSearchParams(window.location.search);
    let changed = false;

    if (params.has('font')) { state.selectedFont = params.get('font'); changed = true; }
    if (params.has('size')) { state.fontSize = parseInt(params.get('size')) || 54; changed = true; }
    if (params.has('color')) { state.styleOptions.textColor = params.get('color'); changed = true; }
    if (params.has('sw')) { state.styleOptions.strokeWidth = parseInt(params.get('sw')) || 0; changed = true; }
    if (params.has('sc')) { state.styleOptions.strokeColor = params.get('sc'); changed = true; }
    if (params.has('sd')) { state.styleOptions.shadowDistance = parseInt(params.get('sd')) || 0; changed = true; }
    if (params.has('sb')) { state.styleOptions.shadowBlur = parseInt(params.get('sb')) || 0; changed = true; }
    if (params.has('sh')) { state.styleOptions.shadowColor = params.get('sh'); changed = true; }
    if (params.has('chroma')) { state.chromaKey = params.get('chroma'); changed = true; }
    if (params.has('mode')) { state.presentationMode = params.get('mode'); changed = true; }
    if (params.has('boxBg')) { state.styleOptions.boxBgColor = params.get('boxBg'); changed = true; }
    if (params.has('boxOp')) { state.styleOptions.boxOpacity = parseInt(params.get('boxOp')) || 0; changed = true; }
    if (params.has('boxRad')) { state.styleOptions.boxRadius = parseInt(params.get('boxRad')) || 0; changed = true; }
    if (params.has('boxPad')) { state.styleOptions.boxPadding = parseInt(params.get('boxPad')) || 0; changed = true; }
    if (params.has('anim')) { state.textAnimation = params.get('anim'); changed = true; }

    if (changed) {
      saveUserSettings();
    }
  }

  function applyInitialUIState() {
    const savedCustomDataUrl = localStorage.getItem('sunday_school_custom_font_dataurl');
    const savedCustomFontName = localStorage.getItem('sunday_school_custom_font_name');
    if (savedCustomDataUrl && savedCustomFontName) {
      let fontStyleEl = document.getElementById('custom-uploaded-font-style');
      if (!fontStyleEl) {
        fontStyleEl = document.createElement('style');
        fontStyleEl.id = 'custom-uploaded-font-style';
        document.head.appendChild(fontStyleEl);
      }
      fontStyleEl.textContent = `@font-face { font-family: "${savedCustomFontName}"; src: url("${savedCustomDataUrl}"); }`;
      if (els.customFontFileName) {
        let displayName = savedCustomFontName.replace(/^CustomFont_/, '').replace(/_/g, ' ');
        els.customFontFileName.textContent = displayName;
      }
    }

    if (state.selectedFont) {
      document.documentElement.style.setProperty('--slide-font-family', state.selectedFont);
      if (els.obsLineText) els.obsLineText.style.fontFamily = state.selectedFont;
    }
    if (els.fontSelect) els.fontSelect.value = state.selectedFont;
    if (els.obsFontSizeRange) els.obsFontSizeRange.value = state.fontSize;
    if (els.fontSizeValBadge) els.fontSizeValBadge.textContent = `${state.fontSize}px`;
    if (els.chromaSelect) els.chromaSelect.value = state.chromaKey;
    if (els.presModeSelect) els.presModeSelect.value = state.presentationMode;
    if (els.francoToggleBtn) els.francoToggleBtn.classList.toggle('active', state.francoAutoTranslate);
    if (els.obsTextAnimSelect) els.obsTextAnimSelect.value = state.textAnimation;
    if (els.btnToggleObsMode) els.btnToggleObsMode.checked = Boolean(state.obsMode === true);
    updateObsModeUI();

    if (els.obsTextColor) els.obsTextColor.value = state.styleOptions.textColor;
    if (els.obsStrokeRange) els.obsStrokeRange.value = state.styleOptions.strokeWidth;
    if (els.obsStrokeColor) els.obsStrokeColor.value = state.styleOptions.strokeColor;
    if (els.obsShadowRange) els.obsShadowRange.value = state.styleOptions.shadowBlur;
    if (els.obsShadowColor) els.obsShadowColor.value = state.styleOptions.shadowColor || '#000000';
    if (els.obsShadowAngleRange) els.obsShadowAngleRange.value = state.styleOptions.shadowAngle !== undefined ? state.styleOptions.shadowAngle : 0;
    if (els.shadowAngleBadge) els.shadowAngleBadge.textContent = `${state.styleOptions.shadowAngle !== undefined ? state.styleOptions.shadowAngle : 0}°`;
    if (els.obsShadowDistanceRange) els.obsShadowDistanceRange.value = state.styleOptions.shadowDistance !== undefined ? state.styleOptions.shadowDistance : 0;
    if (els.shadowDistanceBadge) els.shadowDistanceBadge.textContent = `${state.styleOptions.shadowDistance !== undefined ? state.styleOptions.shadowDistance : 0}px`;

    if (els.obsFontWeightSelect) els.obsFontWeightSelect.value = state.styleOptions.fontWeight;
    if (els.obsScaleModeSelect) els.obsScaleModeSelect.value = state.scaleMode || 'auto';
    updateScaleModeLockState();
    if (els.obsLetterSpacingRange) els.obsLetterSpacingRange.value = state.styleOptions.letterSpacing;
    if (els.obsLineHeightRange) els.obsLineHeightRange.value = state.styleOptions.lineHeight;
    if (els.obsBoxBgColor) els.obsBoxBgColor.value = state.styleOptions.boxBgColor;
    if (els.obsBoxOpacityRange) els.obsBoxOpacityRange.value = state.styleOptions.boxOpacity;
    if (els.obsBoxRadiusRange) els.obsBoxRadiusRange.value = state.styleOptions.boxRadius;
    if (els.obsBoxPaddingRange) els.obsBoxPaddingRange.value = state.styleOptions.boxPadding;

    if (els.btnToggleBold) els.btnToggleBold.classList.toggle('active', state.styleOptions.fontStyle === 'bold');
    if (els.btnToggleItalic) els.btnToggleItalic.classList.toggle('active', state.styleOptions.fontStyle === 'italic');
    if (els.btnToggleUnderline) els.btnToggleUnderline.classList.toggle('active', state.styleOptions.textDecoration === 'underline');

    if (els.btnAlignCenter) els.btnAlignCenter.classList.toggle('active', state.styleOptions.textAlign === 'center');
    if (els.btnAlignRight) els.btnAlignRight.classList.toggle('active', state.styleOptions.textAlign === 'right');
    if (els.btnAlignLeft) els.btnAlignLeft.classList.toggle('active', state.styleOptions.textAlign === 'left');
    if (els.btnAlignJustify) els.btnAlignJustify.classList.toggle('active', state.styleOptions.textAlign === 'justify');

    if (els.obsOverlay) els.obsOverlay.setAttribute('data-chroma', state.chromaKey);
    loadPlaylists();
    renderRecentSession();
    checkOfflineStatusAndToggleInstallBtn();
    detectConnectedScreens();
    updateDisplayButtonUI();
  }

  async function checkOfflineStatusAndToggleInstallBtn() {
    if (!els.btnMenuInstall) return;
    try {
      if ('caches' in window) {
        const keys = await caches.keys();
        if (keys.some(k => k.includes('sunday_school_taranim'))) {
          const cacheName = keys.find(k => k.includes('sunday_school_taranim'));
          const cache = await caches.open(cacheName);
          const matched = await cache.match('./songs_catalog.json');
          if (matched) {
            els.btnMenuInstall.style.display = 'none';
            return;
          }
        }
      }
    } catch (e) {}
  }

