        const maxScroll = el.scrollHeight - el.clientHeight;
        const scrollRatio = maxScroll > 0 ? (el.scrollTop / maxScroll) : 0;
        state.allInOneScrollRatio = scrollRatio;
        debouncedSyncLiveState(40);
